import { z } from 'zod';

export const configSchema = z.object({
  PORT: z.coerce.number().int().positive().default(3000),
  GEMINI_API_KEY: z.string().default(''),
  GEMINI_MODEL: z.string().default('gemini-3.8-flash'),
  MEALPILOT_LLM_MODE: z.enum(['auto', 'live', 'mock']).default('auto'),
  YOUTUBE_API_KEY: z.string().default(''),
  AGENT_MAX_STEPS: z.coerce.number().int().positive().default(12),
  AGENT_MAX_ANALYSES: z.coerce.number().int().positive().default(8),
  AGENT_MAX_SEARCHES: z.coerce.number().int().positive().default(4),
  AGENT_TIMEOUT_MS: z.coerce.number().int().positive().default(90000),
  ANALYSIS_CONCURRENCY: z.coerce.number().int().positive().default(3),
  MEALPILOT_CACHE_DIR: z.string().default(''),
});

export type RawAppConfig = z.infer<typeof configSchema>;

export interface AppConfig extends RawAppConfig {
  effectiveLlmMode: 'live' | 'mock';
}

export function validateConfig(config: Record<string, unknown>): AppConfig {
  const parsed = configSchema.safeParse(config);
  if (!parsed.success) {
    throw new Error(`Configuration validation error: ${parsed.error.message}`);
  }

  const values = parsed.data;

  if (values.MEALPILOT_LLM_MODE === 'live' && !values.GEMINI_API_KEY) {
    throw new Error('GEMINI_API_KEY is required when MEALPILOT_LLM_MODE is set to "live"');
  }

  const effectiveLlmMode: 'live' | 'mock' =
    values.MEALPILOT_LLM_MODE === 'live'
      ? 'live'
      : values.MEALPILOT_LLM_MODE === 'mock'
        ? 'mock'
        : values.GEMINI_API_KEY
          ? 'live'
          : 'mock';

  return {
    ...values,
    effectiveLlmMode,
  };
}

import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppConfig } from './app-config';

@Injectable()
export class AppConfigService {
  constructor(private readonly config: ConfigService<AppConfig, true>) {}

  get port(): number {
    return this.config.get('PORT', { infer: true });
  }

  get geminiApiKey(): string {
    return this.config.get('GEMINI_API_KEY', { infer: true });
  }

  get geminiModel(): string {
    return this.config.get('GEMINI_MODEL', { infer: true });
  }

  get mealpilotLlmMode(): 'auto' | 'live' | 'mock' {
    return this.config.get('MEALPILOT_LLM_MODE', { infer: true });
  }

  get youtubeApiKey(): string {
    return this.config.get('YOUTUBE_API_KEY', { infer: true });
  }

  get agentMaxSteps(): number {
    return this.config.get('AGENT_MAX_STEPS', { infer: true });
  }

  get agentMaxAnalyses(): number {
    return this.config.get('AGENT_MAX_ANALYSES', { infer: true });
  }

  get agentMaxSearches(): number {
    return this.config.get('AGENT_MAX_SEARCHES', { infer: true });
  }

  get agentTimeoutMs(): number {
    return this.config.get('AGENT_TIMEOUT_MS', { infer: true });
  }

  get analysisConcurrency(): number {
    return this.config.get('ANALYSIS_CONCURRENCY', { infer: true });
  }

  get cacheDir(): string {
    return this.config.get('MEALPILOT_CACHE_DIR', { infer: true });
  }

  get effectiveLlmMode(): 'live' | 'mock' {
    return this.config.get('effectiveLlmMode', { infer: true });
  }
}

import { Global, Module } from '@nestjs/common';
import { ConfigModule as NestConfigModule } from '@nestjs/config';
import { validateConfig } from './app-config';
import { AppConfigService } from './app-config.service';

@Global()
@Module({
  imports: [
    NestConfigModule.forRoot({
      isGlobal: true,
      envFilePath: ['.env'],
      validate: validateConfig,
    }),
  ],
  providers: [AppConfigService],
  exports: [AppConfigService],
})
export class AppConfigModule {}

import { validateConfig } from './app-config';

describe('validateConfig', () => {
  it('applies defaults correctly', () => {
    const config = validateConfig({});
    expect(config.PORT).toBe(3000);
    expect(config.GEMINI_MODEL).toBe('gemini-3.8-flash');
    expect(config.MEALPILOT_LLM_MODE).toBe('auto');
    expect(config.effectiveLlmMode).toBe('mock');
    expect(config.AGENT_MAX_STEPS).toBe(12);
    expect(config.AGENT_MAX_ANALYSES).toBe(8);
    expect(config.AGENT_MAX_SEARCHES).toBe(4);
    expect(config.AGENT_TIMEOUT_MS).toBe(90000);
    expect(config.ANALYSIS_CONCURRENCY).toBe(3);
  });

  it('resolves live mode in auto when GEMINI_API_KEY is present', () => {
    const config = validateConfig({
      GEMINI_API_KEY: 'test-key',
    });
    expect(config.effectiveLlmMode).toBe('live');
  });

  it('forces mock mode when MEALPILOT_LLM_MODE is mock even if key is present', () => {
    const config = validateConfig({
      GEMINI_API_KEY: 'test-key',
      MEALPILOT_LLM_MODE: 'mock',
    });
    expect(config.effectiveLlmMode).toBe('mock');
  });

  it('fails fast when MEALPILOT_LLM_MODE is live but GEMINI_API_KEY is missing', () => {
    expect(() =>
      validateConfig({
        MEALPILOT_LLM_MODE: 'live',
      }),
    ).toThrow(/GEMINI_API_KEY is required/);
  });
});

