export interface InteractionTool {
  type: 'function';
  name: string;
  description?: string;
  parameters: Record<string, unknown>;
}

export interface InteractionResponseFormat {
  type: 'text';
  mime_type: 'application/json' | 'text/plain';
  schema?: Record<string, unknown>;
}

export interface InteractionStep {
  type: string;
  id?: string;
  name?: string;
  arguments?: Record<string, unknown>;
  signature?: string;
  content?: Array<{ type: string; text?: string; uri?: string; [k: string]: unknown }>;
  result?: unknown;
  call_id?: string;
  is_error?: boolean;
  [k: string]: unknown;
}

export interface InteractionRequest {
  model?: string;
  system_instruction?: string;
  input: string | InteractionStep[];
  tools?: InteractionTool[];
  response_format?: InteractionResponseFormat;
  store?: boolean;
}

export interface InteractionUsage {
  totalTokens?: number;
  totalInputTokens?: number;
  totalOutputTokens?: number;
}

export interface InteractionResult {
  outputText: string;
  steps: InteractionStep[];
  usage?: InteractionUsage;
  raw?: unknown;
}

export interface LlmClient {
  createInteraction(req: InteractionRequest): Promise<InteractionResult>;
}

export const LLM_CLIENT = Symbol('LLM_CLIENT');

import { Injectable, Logger } from '@nestjs/common';
import { GoogleGenAI } from '@google/genai';
import { AppConfigService } from '../config/app-config.service';
import {
  InteractionRequest,
  InteractionResult,
  InteractionStep,
  LlmClient,
} from './llm-client.interface';

function isRetryableError(error: unknown): boolean {
  if (!error || typeof error !== 'object') return false;
  const status = (error as { status?: number; statusCode?: number }).status ??
    (error as { status?: number; statusCode?: number }).statusCode;

  if (typeof status === 'number' && (status === 429 || status >= 500)) {
    return true;
  }

  const message = String((error as { message?: string }).message || '').toLowerCase();
  return (
    message.includes('429') ||
    message.includes('resource_exhausted') ||
    message.includes('rate limit') ||
    message.includes('503') ||
    message.includes('unavailable') ||
    message.includes('timeout')
  );
}

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

@Injectable()
export class GenAiLlmClient implements LlmClient {
  private readonly logger = new Logger(GenAiLlmClient.name);
  private readonly client: GoogleGenAI;

  constructor(private readonly config: AppConfigService) {
    this.client = new GoogleGenAI({
      apiKey: this.config.geminiApiKey,
    });
  }

  async createInteraction(req: InteractionRequest): Promise<InteractionResult> {
    const model = req.model || this.config.geminiModel || 'gemini-3.8-flash';
    const maxRetries = 2;
    let attempt = 0;

    while (true) {
      try {
        const createParams: Record<string, unknown> = {
          model,
          input: req.input,
          store: req.store ?? false,
        };

        if (req.system_instruction) {
          createParams.system_instruction = req.system_instruction;
        }

        if (req.tools && req.tools.length > 0) {
          createParams.tools = req.tools;
        }

        if (req.response_format) {
          createParams.response_format = req.response_format;
        }

        const res = (await this.client.interactions.create(
          createParams as any,
        )) as any;

        const steps: InteractionStep[] = (res.steps || []).map((step: any) => ({
          ...step,
        }));

        const outputText =
          res.output_text ??
          steps
            .filter((s) => s.type === 'model_output' && Array.isArray(s.content))
            .flatMap((s) => (s.content as any[]) || [])
            .map((c) => c.text || '')
            .join('')
            .trim();

        return {
          outputText: outputText || '',
          steps,
          usage: res.usage
            ? {
                totalTokens: res.usage.total_tokens,
                totalInputTokens: res.usage.total_input_tokens,
                totalOutputTokens: res.usage.total_output_tokens,
              }
            : undefined,
          raw: res,
        };
      } catch (err) {
        attempt++;
        if (attempt <= maxRetries && isRetryableError(err)) {
          const backoff = 500 * Math.pow(2, attempt - 1);
          this.logger.warn(
            `Gemini request failed with retryable error (attempt ${attempt}/${maxRetries}), retrying in ${backoff}ms: ${err}`,
          );
          await delay(backoff);
          continue;
        }
        throw err;
      }
    }
  }
}

import { Injectable } from '@nestjs/common';
import {
  InteractionRequest,
  InteractionResult,
  InteractionStep,
  LlmClient,
} from './llm-client.interface';

@Injectable()
export class MockLlmClient implements LlmClient {
  private cannedResponses: InteractionResult[] = [];

  queueResponse(res: InteractionResult): void {
    this.cannedResponses.push(res);
  }

  async createInteraction(req: InteractionRequest): Promise<InteractionResult> {
    if (this.cannedResponses.length > 0) {
      return this.cannedResponses.shift()!;
    }

    // Default mock behavior for structured or unstructured input
    if (req.response_format?.schema) {
      return {
        outputText: JSON.stringify({
          recipeName: 'Mock Dish',
          ingredients: [{ name: 'olive oil' }, { name: 'vegetables' }],
          steps: ['Chop vegetables', 'Cook in olive oil'],
          allergens: [],
          crossContactNotes: [],
          sodiumSources: [],
          nutritionSignals: ['whole-foods'],
          restrictionTags: ['vegetarian'],
          summary: 'Mock analysis summary',
          coverage: 'full',
        }),
        steps: [
          {
            type: 'model_output',
            content: [{ type: 'text', text: 'Mock dish generated' }],
          },
        ],
      };
    }

    const steps: InteractionStep[] = [
      {
        type: 'model_output',
        content: [{ type: 'text', text: 'Mock LLM response' }],
      },
    ];

    return {
      outputText: 'Mock LLM response',
      steps,
    };
  }
}

import { Module, Provider } from '@nestjs/common';
import { AppConfigModule } from '../config/config.module';
import { AppConfigService } from '../config/app-config.service';
import { LLM_CLIENT, LlmClient } from './llm-client.interface';
import { GenAiLlmClient } from './genai-llm-client';
import { MockLlmClient } from './mock-llm-client';

const llmClientProvider: Provider = {
  provide: LLM_CLIENT,
  useFactory: (config: AppConfigService): LlmClient => {
    if (config.effectiveLlmMode === 'live') {
      return new GenAiLlmClient(config);
    }
    return new MockLlmClient();
  },
  inject: [AppConfigService],
};

@Module({
  imports: [AppConfigModule],
  providers: [llmClientProvider, GenAiLlmClient, MockLlmClient],
  exports: [LLM_CLIENT, GenAiLlmClient, MockLlmClient],
})
export class LlmModule {}

import { Test } from '@nestjs/testing';
import { LLM_CLIENT } from './llm-client.interface';
import { LlmModule } from './llm.module';
import { AppConfigService } from '../config/app-config.service';
import { MockLlmClient } from './mock-llm-client';
import { GenAiLlmClient } from './genai-llm-client';

describe('LlmModule provider factory', () => {
  it('provides MockLlmClient when effective mode is mock', async () => {
    const moduleRef = await Test.createTestingModule({
      imports: [LlmModule],
    })
      .overrideProvider(AppConfigService)
      .useValue({
        effectiveLlmMode: 'mock',
        geminiApiKey: '',
        geminiModel: 'gemini-3.8-flash',
      })
      .compile();

    const client = moduleRef.get(LLM_CLIENT);
    expect(client).toBeInstanceOf(MockLlmClient);
  });

  it('provides GenAiLlmClient when effective mode is live', async () => {
    const moduleRef = await Test.createTestingModule({
      imports: [LlmModule],
    })
      .overrideProvider(AppConfigService)
      .useValue({
        effectiveLlmMode: 'live',
        geminiApiKey: 'test-key',
        geminiModel: 'gemini-3.8-flash',
      })
      .compile();

    const client = moduleRef.get(LLM_CLIENT);
    expect(client).toBeInstanceOf(GenAiLlmClient);
  });
});

