import { z } from 'zod';
import { CanonicalAllergen, CANONICAL_ALLERGENS } from '../allergy.util';

export const ANALYSIS_SCHEMA_VERSION = 2;

export const KNOWN_NUTRITION_SIGNALS = [
  'low-sodium',
  'moderate-sodium',
  'low-carb',
  'high-protein',
  'high-fiber',
  'quick-prep',
  'whole-foods',
] as const;
export type NutritionSignal = (typeof KNOWN_NUTRITION_SIGNALS)[number];

export const KNOWN_RESTRICTION_TAGS = [
  'vegan',
  'vegetarian',
  'gluten-free',
  'dairy-free',
  'nut-free',
  'low-sodium',
  'low-carb',
  'high-protein',
  'halal',
  'kosher',
] as const;
export type RestrictionTag = (typeof KNOWN_RESTRICTION_TAGS)[number];

export const AllergenConfidenceSchema = z.enum([
  'confirmed',
  'likely',
  'possible',
]);
export type AllergenConfidence = z.infer<typeof AllergenConfidenceSchema>;

export const AllergenEvidenceSchema = z.object({
  allergen: z.enum(CANONICAL_ALLERGENS),
  evidence: z
    .string()
    .describe("Spoken or visual evidence, e.g. 'spoken at 02:14: a spoonful of peanut butter'"),
  timestamp: z.string().optional(),
  confidence: AllergenConfidenceSchema,
});
export type AllergenEvidence = z.infer<typeof AllergenEvidenceSchema>;

export const IngredientSchema = z.object({
  name: z.string(),
  quantity: z.string().optional(),
  timestamp: z.string().optional(),
});
export type Ingredient = z.infer<typeof IngredientSchema>;

export const AnalysisOutputSchema = z.object({
  recipeName: z.string(),
  servings: z.number().optional(),
  durationSec: z.number().optional(),
  ingredients: z.array(IngredientSchema),
  steps: z.array(z.string()),
  allergens: z.array(AllergenEvidenceSchema),
  crossContactNotes: z.array(z.string()).default([]),
  sodiumSources: z.array(z.string()).default([]),
  nutritionSignals: z.array(z.enum(KNOWN_NUTRITION_SIGNALS)).default([]),
  restrictionTags: z.array(z.enum(KNOWN_RESTRICTION_TAGS)).default([]),
  summary: z.string(),
  coverage: z.enum(['full', 'partial']).default('full'),
});
export type AnalysisOutput = z.infer<typeof AnalysisOutputSchema>;

export interface VideoAnalysis extends AnalysisOutput {
  videoId: string;
  title: string;
  channel: string;
  status: 'ok' | 'unavailable';
  error?: string;
  provider: 'gemini' | 'mock';
  model: string;
  analyzedAt: string;
  schemaVersion: number;
  // Computed helpers for backwards-compatibility:
  transcript: string;
  detectedAllergens: string[];
}

/**
 * Standard JSON Schema compatible with Gemini API response_format.
 */
export const ANALYSIS_JSON_SCHEMA: Record<string, unknown> = {
  type: 'object',
  properties: {
    recipeName: {
      type: 'string',
      description: 'The primary dish or recipe prepared in the video.',
    },
    servings: {
      type: 'number',
      description: 'Approximate number of servings if specified or discernible.',
    },
    durationSec: {
      type: 'number',
      description: 'Video length in seconds if discernible.',
    },
    ingredients: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          quantity: { type: 'string' },
          timestamp: { type: 'string' },
        },
        required: ['name'],
      },
      description: 'Explicit ingredients used in the preparation.',
    },
    steps: {
      type: 'array',
      items: { type: 'string' },
      description: 'Step-by-step cooking steps observed.',
    },
    allergens: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          allergen: {
            type: 'string',
            enum: [...CANONICAL_ALLERGENS],
          },
          evidence: {
            type: 'string',
            description: 'Explicit evidence with quote or observation.',
          },
          timestamp: { type: 'string' },
          confidence: {
            type: 'string',
            enum: ['confirmed', 'likely', 'possible'],
          },
        },
        required: ['allergen', 'evidence', 'confidence'],
      },
      description: 'EU 14 major allergens observed or suspected with confidence.',
    },
    crossContactNotes: {
      type: 'array',
      items: { type: 'string' },
      description: 'Shared fryers, cutting boards, or facility cross-contact warnings.',
    },
    sodiumSources: {
      type: 'array',
      items: { type: 'string' },
      description: 'High sodium ingredients such as soy sauce, bouillon, cured meats, table salt.',
    },
    nutritionSignals: {
      type: 'array',
      items: {
        type: 'string',
        enum: [...KNOWN_NUTRITION_SIGNALS],
      },
    },
    restrictionTags: {
      type: 'array',
      items: {
        type: 'string',
        enum: [...KNOWN_RESTRICTION_TAGS],
      },
    },
    summary: {
      type: 'string',
      description: 'Concise summary of the dish, nutrition fit, and prep style.',
    },
    coverage: {
      type: 'string',
      enum: ['full', 'partial'],
      description: 'Whether the full recipe/ingredients could be confidently observed.',
    },
  },
  required: [
    'recipeName',
    'ingredients',
    'steps',
    'allergens',
    'crossContactNotes',
    'sodiumSources',
    'nutritionSignals',
    'restrictionTags',
    'summary',
    'coverage',
  ],
};

import {
  AnalysisOutputSchema,
  ANALYSIS_JSON_SCHEMA,
  ANALYSIS_SCHEMA_VERSION,
} from './analysis.schema';

describe('Analysis schema v2', () => {
  it('validates correct analysis payload', () => {
    const valid = {
      recipeName: 'Lentil Stew',
      servings: 4,
      ingredients: [{ name: 'brown lentils' }, { name: 'carrots' }],
      steps: ['Sauté carrots', 'Simmer lentils with water'],
      allergens: [
        {
          allergen: 'celery',
          evidence: 'chopped celery added at 01:15',
          confidence: 'confirmed',
        },
      ],
      crossContactNotes: [],
      sodiumSources: ['sea salt'],
      nutritionSignals: ['low-sodium', 'high-fiber'],
      restrictionTags: ['vegan', 'gluten-free'],
      summary: 'A nutritious low-sodium vegetable and lentil stew.',
      coverage: 'full',
    };

    const parsed = AnalysisOutputSchema.safeParse(valid);
    expect(parsed.success).toBe(true);
    expect(ANALYSIS_SCHEMA_VERSION).toBe(2);
  });

  it('rejects invalid allergen enum', () => {
    const invalid = {
      recipeName: 'Salad',
      ingredients: [{ name: 'lettuce' }],
      steps: ['Toss'],
      allergens: [
        {
          allergen: 'not-a-real-allergen',
          evidence: 'none',
          confidence: 'likely',
        },
      ],
      summary: 'Salad',
    };

    const parsed = AnalysisOutputSchema.safeParse(invalid);
    expect(parsed.success).toBe(false);
  });

  it('provides JSON schema with required fields', () => {
    expect(ANALYSIS_JSON_SCHEMA.required).toContain('recipeName');
    expect(ANALYSIS_JSON_SCHEMA.required).toContain('allergens');
  });
});

import { VideoAnalysis } from './analysis.schema';

export interface VideoTarget {
  videoId: string;
  title: string;
  channel: string;
}

export interface VideoAnalyzer {
  provider(): 'gemini' | 'mock';
  model(): string;
  analyze(target: VideoTarget): Promise<VideoAnalysis>;
}

export const VIDEO_ANALYZER = Symbol('VIDEO_ANALYZER');

import { Injectable } from '@nestjs/common';
import {
  AllergenEvidence,
  ANALYSIS_SCHEMA_VERSION,
  NutritionSignal,
  RestrictionTag,
  VideoAnalysis,
} from './analysis.schema';
import { VideoAnalyzer, VideoTarget } from './video-analyzer.interface';

@Injectable()
export class MockVideoAnalyzer implements VideoAnalyzer {
  provider(): 'gemini' | 'mock' {
    return 'mock';
  }

  model(): string {
    return 'mock';
  }

  async analyze(target: VideoTarget): Promise<VideoAnalysis> {
    const hay = `${target.title} ${target.channel}`.toLowerCase();
    const has = (...words: string[]) => words.some((w) => hay.includes(w));

    const ingredients = [
      { name: 'olive oil' },
      { name: 'garlic' },
      { name: 'vegetables' },
      { name: 'herbs' },
    ];
    const nutritionSignals: NutritionSignal[] = [];
    const allergens: AllergenEvidence[] = [];
    const restrictionTags: RestrictionTag[] = [];
    const sodiumSources: string[] = [];

    if (has('vegan')) {
      restrictionTags.push('vegan', 'vegetarian', 'dairy-free');
      ingredients.push(
        { name: 'chickpeas' },
        { name: 'leafy greens' },
        { name: 'lemon' },
      );
    } else if (
      has('vegetarian', 'veggie', 'lentil', 'salad', 'stir fry', 'stir-fry')
    ) {
      restrictionTags.push('vegetarian');
      ingredients.push({ name: 'lentils' }, { name: 'brown rice' });
    }

    if (has('chicken', 'salmon', 'fish', 'turkey', 'beef')) {
      ingredients.push(
        has('salmon', 'fish')
          ? { name: 'salmon fillet' }
          : { name: 'lean protein' },
      );
      restrictionTags.push('high-protein');
    }

    if (has('gluten-free', 'gluten free', 'quinoa', 'rice')) {
      restrictionTags.push('gluten-free');
    } else {
      ingredients.push({ name: 'whole-grain bread' });
    }

    if (has('low sodium', 'low-sodium', 'hypertension', 'blood pressure')) {
      nutritionSignals.push('low-sodium');
    } else {
      nutritionSignals.push('moderate-sodium');
      sodiumSources.push('table salt');
    }

    if (has('low carb', 'diabetes', 'keto')) {
      nutritionSignals.push('low-carb');
    }

    if (has('quick', '15-minute', '15 minute', 'easy', 'dinner')) {
      nutritionSignals.push('quick-prep');
    }

    nutritionSignals.push('whole-foods');

    if (has('peanut', 'satay', 'pad thai')) {
      ingredients.push({ name: 'peanuts' }, { name: 'peanut sauce' });
      allergens.push({
        allergen: 'peanuts',
        evidence: `Keyword match in "${target.title}" (peanut/satay/pad thai)`,
        confidence: 'confirmed',
      });
    }

    if (has('shrimp', 'shellfish', 'paella', 'seafood')) {
      ingredients.push({ name: 'shrimp' });
      allergens.push({
        allergen: 'crustaceans',
        evidence: `Keyword match in "${target.title}" (shrimp/shellfish/seafood)`,
        confidence: 'confirmed',
      });
    }

    if (has('cheese', 'cream', 'dairy')) {
      allergens.push({
        allergen: 'milk',
        evidence: `Keyword match in "${target.title}" (cheese/cream/dairy)`,
        confidence: 'confirmed',
      });
    }

    if (has('bread', 'pasta') && !has('gluten-free', 'gluten free')) {
      allergens.push({
        allergen: 'gluten',
        evidence: `Keyword match in "${target.title}" (bread/pasta)`,
        confidence: 'confirmed',
      });
    }

    const steps = [
      `Prepare ${ingredients.slice(0, 4).map((i) => i.name).join(', ')}`,
      'Season lightly and cook over medium heat',
      'Plate and serve immediately',
    ];

    const transcript =
      `Mock transcript for "${target.title}" by ${target.channel}: ` +
      `prepare ${ingredients.slice(0, 4).map((i) => i.name).join(', ')}, season lightly, ` +
      `cook and serve. (Offline mock — set GEMINI_API_KEY for live Gemini analysis.)`;

    const summary =
      `Mock analysis of "${target.title}": ` +
      `${restrictionTags.length ? `tags ${restrictionTags.join(', ')}; ` : ''}` +
      `${nutritionSignals.length ? `signals ${nutritionSignals.join(', ')}; ` : ''}` +
      `${allergens.length ? `possible allergens: ${allergens.map((a) => a.allergen).join(', ')}.` : 'no common allergens detected in mock data.'}`;

    return {
      videoId: target.videoId,
      title: target.title,
      channel: target.channel,
      recipeName: target.title,
      ingredients,
      steps,
      allergens,
      crossContactNotes: [],
      sodiumSources,
      nutritionSignals,
      restrictionTags,
      summary,
      coverage: 'full',
      status: 'ok',
      provider: 'mock',
      model: 'mock',
      analyzedAt: new Date().toISOString(),
      schemaVersion: ANALYSIS_SCHEMA_VERSION,
      transcript,
      detectedAllergens: allergens.map((a) => a.allergen),
    };
  }
}

import { Inject, Injectable, Logger } from '@nestjs/common';
import { AppConfigService } from '../../config/app-config.service';
import { LLM_CLIENT, LlmClient } from '../../llm/llm-client.interface';
import {
  AnalysisOutput,
  AnalysisOutputSchema,
  ANALYSIS_JSON_SCHEMA,
  ANALYSIS_SCHEMA_VERSION,
  VideoAnalysis,
} from './analysis.schema';
import { VideoAnalyzer, VideoTarget } from './video-analyzer.interface';

@Injectable()
export class GeminiVideoAnalyzer implements VideoAnalyzer {
  private readonly logger = new Logger(GeminiVideoAnalyzer.name);

  constructor(
    @Inject(LLM_CLIENT) private readonly llm: LlmClient,
    private readonly config: AppConfigService,
  ) {}

  provider(): 'gemini' | 'mock' {
    return 'gemini';
  }

  model(): string {
    return this.config.geminiModel || 'gemini-3.8-flash';
  }

  async analyze(target: VideoTarget): Promise<VideoAnalysis> {
    const model = this.model();
    const videoUri = `https://www.youtube.com/watch?v=${target.videoId}`;

    const promptText = [
      `You are a nutrition-aware culinary assistant analyzing a YouTube cooking video.`,
      `Video: "${target.title}" by ${target.channel} (id: ${target.videoId}).`,
      `Watch and analyze this video. Extract recipe details, observed ingredients, cooking steps, EU 14 allergens with timestamp/spoken evidence, cross-contact risks, sodium sources, nutrition signals, and restriction tags.`,
      `Be conservative: when unsure whether an allergen is present, mark confidence as "possible" or note in crossContactNotes and summary.`,
      `Return strict structured JSON adhering to the schema.`,
    ].join('\n');

    try {
      const interaction = await this.llm.createInteraction({
        model,
        store: false,
        input: [
          {
            type: 'user_input',
            content: [
              {
                type: 'video',
                uri: videoUri,
              },
              {
                type: 'text',
                text: promptText,
              },
            ],
          },
        ],
        response_format: {
          type: 'text',
          mime_type: 'application/json',
          schema: ANALYSIS_JSON_SCHEMA,
        },
      });

      const parsed = this.parseOutput(interaction.outputText);
      if (parsed.success) {
        return this.toVideoAnalysis(target, parsed.data, model);
      }

      this.logger.warn(
        `Initial JSON schema validation failed for ${target.videoId}: ${parsed.error}. Retrying once with error feedback...`,
      );

      // Retry once with error feedback
      const retryInteraction = await this.llm.createInteraction({
        model,
        store: false,
        input: [
          {
            type: 'user_input',
            content: [
              {
                type: 'video',
                uri: videoUri,
              },
              {
                type: 'text',
                text: `${promptText}\n\nATTENTION: Your previous JSON output was invalid:\n${parsed.error}\nPlease correct it and ensure complete compliance with the required schema.`,
              },
            ],
          },
        ],
        response_format: {
          type: 'text',
          mime_type: 'application/json',
          schema: ANALYSIS_JSON_SCHEMA,
        },
      });

      const retryParsed = this.parseOutput(retryInteraction.outputText);
      if (retryParsed.success) {
        return this.toVideoAnalysis(target, retryParsed.data, model);
      }

      return this.unavailable(
        target,
        model,
        `Schema validation retry failed: ${retryParsed.error}`,
      );
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      this.logger.warn(`Gemini video analysis failed for ${target.videoId}: ${message}`);

      const reason =
        message.toLowerCase().includes('not found') ||
        message.toLowerCase().includes('private') ||
        message.toLowerCase().includes('permission') ||
        message.toLowerCase().includes('unsupported')
          ? 'video_not_public'
          : message;

      return this.unavailable(target, model, reason);
    }
  }

  private parseOutput(
    rawText: string,
  ): { success: true; data: AnalysisOutput } | { success: false; error: string } {
    try {
      const trimmed = rawText.trim();
      const parsedJson = JSON.parse(trimmed);
      const validated = AnalysisOutputSchema.safeParse(parsedJson);
      if (!validated.success) {
        return { success: false, error: validated.error.message };
      }
      return { success: true, data: validated.data };
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      return { success: false, error: `Invalid JSON output: ${msg}` };
    }
  }

  private toVideoAnalysis(
    target: VideoTarget,
    data: AnalysisOutput,
    model: string,
  ): VideoAnalysis {
    return {
      videoId: target.videoId,
      title: target.title,
      channel: target.channel,
      ...data,
      status: 'ok',
      provider: 'gemini',
      model,
      analyzedAt: new Date().toISOString(),
      schemaVersion: ANALYSIS_SCHEMA_VERSION,
      transcript: data.steps.join('. '),
      detectedAllergens: data.allergens.map((a) => a.allergen),
    };
  }

  private unavailable(
    target: VideoTarget,
    model: string,
    error: string,
  ): VideoAnalysis {
    return {
      videoId: target.videoId,
      title: target.title,
      channel: target.channel,
      recipeName: target.title,
      ingredients: [],
      steps: [],
      allergens: [],
      crossContactNotes: [],
      sodiumSources: [],
      nutritionSignals: [],
      restrictionTags: [],
      summary: `Analysis unavailable: ${error}`,
      coverage: 'partial',
      status: 'unavailable',
      error,
      provider: 'gemini',
      model,
      analyzedAt: new Date().toISOString(),
      schemaVersion: ANALYSIS_SCHEMA_VERSION,
      transcript: '',
      detectedAllergens: [],
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import * as fs from 'fs';
import * as path from 'path';
import { ANALYSIS_SCHEMA_VERSION, VideoAnalysis } from './analyzers/analysis.schema';

const SEED_FILE = path.join(process.cwd(), 'data', 'videos.seed.json');
const DEFAULT_TTL_MS = 30 * 24 * 60 * 60 * 1000; // 30 days

function sanitize(str: string): string {
  return str.replace(/[^a-zA-Z0-9_-]/g, '_');
}

@Injectable()
export class TranscriptCacheService {
  private readonly logger = new Logger(TranscriptCacheService.name);
  private readonly memory = new Map<string, VideoAnalysis>();

  cacheDir(): string {
    const dir =
      process.env.MEALPILOT_CACHE_DIR || path.join(process.cwd(), 'data', 'cache');
    fs.mkdirSync(dir, { recursive: true });
    return dir;
  }

  private keyFor(
    videoId: string,
    provider: string,
    model: string,
    version = ANALYSIS_SCHEMA_VERSION,
  ): string {
    return `${videoId}.${provider}.${sanitize(model)}.v${version}`;
  }

  private fileFor(
    videoId: string,
    provider: string,
    model: string,
    version = ANALYSIS_SCHEMA_VERSION,
  ): string {
    return path.join(
      this.cacheDir(),
      `${this.keyFor(videoId, provider, model, version)}.json`,
    );
  }

  private isExpired(entry: VideoAnalysis, ttlMs = DEFAULT_TTL_MS): boolean {
    if (!entry.analyzedAt) return true;
    const time = new Date(entry.analyzedAt).getTime();
    if (isNaN(time)) return true;
    return Date.now() - time > ttlMs;
  }

  get(
    videoId: string,
    provider: 'gemini' | 'mock' = 'gemini',
    model = 'gemini-3.8-flash',
  ): VideoAnalysis | null {
    const cacheKey = this.keyFor(videoId, provider, model);
    if (this.memory.has(cacheKey)) {
      const memEntry = this.memory.get(cacheKey)!;
      if (this.isExpired(memEntry)) {
        this.memory.delete(cacheKey);
        return null;
      }
      return memEntry;
    }

    const filePath = this.fileFor(videoId, provider, model);
    if (fs.existsSync(filePath)) {
      try {
        const parsed = JSON.parse(
          fs.readFileSync(filePath, 'utf8'),
        ) as VideoAnalysis;

        if (parsed.schemaVersion !== ANALYSIS_SCHEMA_VERSION) {
          return null;
        }

        if (this.isExpired(parsed)) {
          this.logger.debug(`Cache expired for ${cacheKey}`);
          try {
            fs.unlinkSync(filePath);
          } catch {
            // ignore
          }
          return null;
        }

        this.memory.set(cacheKey, parsed);
        return parsed;
      } catch (err) {
        this.logger.warn(`Ignoring corrupt cache file ${filePath}: ${err}`);
        return null;
      }
    }

    return null;
  }

  set(entry: VideoAnalysis, currentSystemMode?: 'live' | 'mock'): VideoAnalysis {
    // Never persist unavailable results
    if (entry.status === 'unavailable') {
      return entry;
    }

    // Never persist mock results while in live mode
    if (currentSystemMode === 'live' && entry.provider === 'mock') {
      return entry;
    }

    const cacheKey = this.keyFor(
      entry.videoId,
      entry.provider,
      entry.model,
      entry.schemaVersion || ANALYSIS_SCHEMA_VERSION,
    );

    this.memory.set(cacheKey, entry);

    try {
      const filePath = this.fileFor(
        entry.videoId,
        entry.provider,
        entry.model,
        entry.schemaVersion || ANALYSIS_SCHEMA_VERSION,
      );
      fs.writeFileSync(filePath, JSON.stringify(entry, null, 2));
    } catch (err) {
      this.logger.warn(`Could not persist cache for ${entry.videoId}: ${err}`);
    }

    return entry;
  }

  list(): VideoAnalysis[] {
    const dir = this.cacheDir();
    const versionPattern = new RegExp(`\\.v${ANALYSIS_SCHEMA_VERSION}\\.json$`);
    const files = fs.existsSync(dir)
      ? fs.readdirSync(dir).filter((f) => versionPattern.test(f))
      : [];

    const out: VideoAnalysis[] = [];
    for (const f of files) {
      try {
        const parsed = JSON.parse(
          fs.readFileSync(path.join(dir, f), 'utf8'),
        ) as VideoAnalysis;
        if (!this.isExpired(parsed)) {
          out.push(parsed);
        }
      } catch {
        // skip corrupt files
      }
    }

    for (const [, entry] of this.memory) {
      if (
        !this.isExpired(entry) &&
        !out.find((e) => e.videoId === entry.videoId && e.provider === entry.provider)
      ) {
        out.push(entry);
      }
    }

    return out;
  }

  clear(videoId?: string): { cleared: number } {
    const dir = this.cacheDir();
    if (videoId) {
      let count = 0;
      for (const [key] of this.memory) {
        if (key.startsWith(`${videoId}.`)) {
          this.memory.delete(key);
        }
      }
      if (fs.existsSync(dir)) {
        for (const f of fs.readdirSync(dir)) {
          if (f.startsWith(`${videoId}.`)) {
            try {
              fs.unlinkSync(path.join(dir, f));
              count++;
            } catch {
              // ignore
            }
          }
        }
      }
      return { cleared: count || 1 };
    }

    const n = this.list().length;
    this.memory.clear();
    if (fs.existsSync(dir)) {
      for (const f of fs.readdirSync(dir).filter((f) => f.endsWith('.json'))) {
        try {
          fs.unlinkSync(path.join(dir, f));
        } catch {
          // ignore
        }
      }
    }
    return { cleared: n };
  }

  loadSeed(): Array<{ videoId: string; title: string; channel: string }> {
    try {
      if (!fs.existsSync(SEED_FILE)) return [];
      const parsed = JSON.parse(fs.readFileSync(SEED_FILE, 'utf8'));
      return Array.isArray(parsed) ? parsed : parsed.videos ?? [];
    } catch {
      return [];
    }
  }
}

import { Inject, Injectable } from '@nestjs/common';
import { AppConfigService } from '../config/app-config.service';
import { VideoAnalysis } from './analyzers/analysis.schema';
import {
  VIDEO_ANALYZER,
  VideoAnalyzer,
} from './analyzers/video-analyzer.interface';
import { TranscriptCacheService } from './transcript-cache.service';

export interface AnalysisResultWithCacheMeta {
  analysis: VideoAnalysis;
  fromCache: boolean;
}

@Injectable()
export class VideoAnalysisService {
  constructor(
    private readonly cache: TranscriptCacheService,
    @Inject(VIDEO_ANALYZER) private readonly analyzer: VideoAnalyzer,
    private readonly config: AppConfigService,
  ) {}

  async analyzeWithMeta(
    videoId: string,
    title: string,
    channel: string,
  ): Promise<AnalysisResultWithCacheMeta> {
    const cached = this.cache.get(
      videoId,
      this.analyzer.provider(),
      this.analyzer.model(),
    );
    if (cached) {
      return { analysis: cached, fromCache: true };
    }

    const result = await this.analyzer.analyze({ videoId, title, channel });
    if (result.status === 'ok') {
      this.cache.set(result, this.config.effectiveLlmMode);
    }

    return { analysis: result, fromCache: false };
  }

  async analyze(
    videoId: string,
    title: string,
    channel: string,
  ): Promise<VideoAnalysis> {
    const { analysis } = await this.analyzeWithMeta(videoId, title, channel);
    return analysis;
  }

  provider(): 'gemini' | 'mock' {
    return this.analyzer.provider();
  }

  model(): string {
    return this.analyzer.model();
  }
}

