export interface YouTubeVideoDetails {
  videoId: string;
  title: string;
  channel: string;
  durationSec: number;
  privacyStatus: string;
  embeddable: boolean;
  language?: string;
}

export interface YouTubeSearchOptions {
  maxResults?: number;
  relevanceLanguage?: string;
}

export interface IYouTubeService {
  search(query: string, opts?: YouTubeSearchOptions): Promise<string[]>;
  getDetails(ids: string[]): Promise<YouTubeVideoDetails[]>;
  getQuotaUsage(): { unitsUsedToday: number; dailyCap: number };
}

export const YOUTUBE_SERVICE = Symbol('YOUTUBE_SERVICE');

export function parseIsoDuration(duration: string): number {
  if (!duration) return 0;
  const match = duration.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
  if (!match) return 0;
  const hours = parseInt(match[1] || '0', 10);
  const minutes = parseInt(match[2] || '0', 10);
  const seconds = parseInt(match[3] || '0', 10);
  return hours * 3600 + minutes * 60 + seconds;
}

import { Injectable, Logger } from '@nestjs/common';
import { AppConfigService } from '../config/app-config.service';
import {
  IYouTubeService,
  parseIsoDuration,
  YouTubeSearchOptions,
  YouTubeVideoDetails,
} from './youtube.interface';

interface SearchCacheEntry {
  ids: string[];
  expiresAt: number;
}

@Injectable()
export class YouTubeService implements IYouTubeService {
  private readonly logger = new Logger(YouTubeService.name);
  private readonly searchCache = new Map<string, SearchCacheEntry>();

  private unitsUsedToday = 0;
  private currentDay = new Date().toISOString().slice(0, 10);
  private readonly dailyCap = 9000; // Leave margin below the 10,000 unit default

  constructor(private readonly config: AppConfigService) {}

  private checkAndResetQuota(): void {
    const today = new Date().toISOString().slice(0, 10);
    if (today !== this.currentDay) {
      this.currentDay = today;
      this.unitsUsedToday = 0;
    }
  }

  getQuotaUsage(): { unitsUsedToday: number; dailyCap: number } {
    this.checkAndResetQuota();
    return {
      unitsUsedToday: this.unitsUsedToday,
      dailyCap: this.dailyCap,
    };
  }

  async search(query: string, opts?: YouTubeSearchOptions): Promise<string[]> {
    const apiKey = this.config.youtubeApiKey;
    if (!apiKey) {
      this.logger.warn('YOUTUBE_API_KEY is not configured; search returning empty');
      return [];
    }

    const normQuery = query.trim().toLowerCase();
    const cached = this.searchCache.get(normQuery);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.ids;
    }

    this.checkAndResetQuota();
    if (this.unitsUsedToday + 100 > this.dailyCap) {
      throw new Error(
        `YouTube API daily quota threshold reached (${this.unitsUsedToday}/${this.dailyCap} units). Search refused.`,
      );
    }

    const maxResults = Math.min(opts?.maxResults ?? 10, 10);
    const params = new URLSearchParams({
      part: 'snippet',
      type: 'video',
      videoEmbeddable: 'true',
      safeSearch: 'strict',
      videoDuration: 'medium', // 4-20 minutes
      maxResults: String(maxResults),
      q: query,
      key: apiKey,
    });

    if (opts?.relevanceLanguage) {
      params.set('relevanceLanguage', opts.relevanceLanguage);
    }

    const url = `https://www.googleapis.com/youtube/v3/search?${params.toString()}`;
    const res = await fetch(url);
    this.unitsUsedToday += 100;

    if (!res.ok) {
      const errBody = await res.text();
      this.logger.error(`YouTube search.list failed (${res.status}): ${errBody}`);
      throw new Error(`YouTube search API error: ${res.status}`);
    }

    const data = (await res.json()) as any;
    const ids: string[] = (data.items || [])
      .map((item: any) => item.id?.videoId)
      .filter(Boolean);

    // Cache for 24 hours
    this.searchCache.set(normQuery, {
      ids,
      expiresAt: Date.now() + 24 * 60 * 60 * 1000,
    });

    return ids;
  }

  async getDetails(ids: string[]): Promise<YouTubeVideoDetails[]> {
    const apiKey = this.config.youtubeApiKey;
    if (!apiKey || ids.length === 0) {
      return [];
    }

    this.checkAndResetQuota();
    const results: YouTubeVideoDetails[] = [];
    const chunkSize = 50;

    for (let i = 0; i < ids.length; i += chunkSize) {
      const chunk = ids.slice(i, i + chunkSize);
      if (this.unitsUsedToday + 1 > this.dailyCap) {
        this.logger.warn('YouTube quota reached during getDetails batch');
        break;
      }

      const params = new URLSearchParams({
        part: 'snippet,contentDetails,status',
        id: chunk.join(','),
        key: apiKey,
      });

      const url = `https://www.googleapis.com/youtube/v3/videos?${params.toString()}`;
      const res = await fetch(url);
      this.unitsUsedToday += 1;

      if (!res.ok) {
        const errBody = await res.text();
        this.logger.error(`YouTube videos.list failed (${res.status}): ${errBody}`);
        continue;
      }

      const data = (await res.json()) as any;
      for (const item of data.items || []) {
        const durationSec = parseIsoDuration(item.contentDetails?.duration || '');
        const privacyStatus = item.status?.privacyStatus || 'unknown';
        const embeddable = item.status?.embeddable !== false;

        // Filter out non-public or excessively long videos (> 25 minutes = 1500s)
        if (privacyStatus !== 'public' || !embeddable || durationSec > 1500) {
          continue;
        }

        results.push({
          videoId: item.id,
          title: item.snippet?.title || `YouTube video ${item.id}`,
          channel: item.snippet?.channelTitle || 'Unknown channel',
          durationSec,
          privacyStatus,
          embeddable,
          language: item.snippet?.defaultLanguage || item.snippet?.defaultAudioLanguage,
        });
      }
    }

    return results;
  }
}

import { Injectable } from '@nestjs/common';
import {
  IYouTubeService,
  YouTubeSearchOptions,
  YouTubeVideoDetails,
} from './youtube.interface';

@Injectable()
export class FakeYouTubeService implements IYouTubeService {
  private cannedDetails = new Map<string, YouTubeVideoDetails>();
  private cannedSearches = new Map<string, string[]>();

  constructor() {
    // Seed with common test videos
    this.addVideo({
      videoId: 'veg-low-sodium-01',
      title: 'Low-Sodium Vegetarian Lentil Soup',
      channel: 'Healthy Kitchen',
      durationSec: 620,
      privacyStatus: 'public',
      embeddable: true,
    });
    this.addVideo({
      videoId: 'vegan-quinoa-02',
      title: 'Vegan Quinoa Buddha Bowl (Gluten-Free)',
      channel: 'Plant Table',
      durationSec: 540,
      privacyStatus: 'public',
      embeddable: true,
    });
    this.addVideo({
      videoId: 'quick-chicken-03',
      title: 'Quick 15-Minute Chicken and Veggie Stir Fry',
      channel: 'Weeknight Cooks',
      durationSec: 900,
      privacyStatus: 'public',
      embeddable: true,
    });
    this.addVideo({
      videoId: 'peanut-satay-04',
      title: 'Peanut Satay Noodles',
      channel: 'Wok House',
      durationSec: 480,
      privacyStatus: 'public',
      embeddable: true,
    });
  }

  addVideo(video: YouTubeVideoDetails): void {
    this.cannedDetails.set(video.videoId, video);
  }

  addSearchResult(query: string, ids: string[]): void {
    this.cannedSearches.set(query.toLowerCase(), ids);
  }

  getQuotaUsage(): { unitsUsedToday: number; dailyCap: number } {
    return { unitsUsedToday: 0, dailyCap: 9000 };
  }

  async search(query: string, opts?: YouTubeSearchOptions): Promise<string[]> {
    const norm = query.toLowerCase();
    for (const [q, ids] of this.cannedSearches) {
      if (norm.includes(q) || q.includes(norm)) {
        return ids.slice(0, opts?.maxResults ?? 10);
      }
    }

    // Default: return all canned videos matching keyword, or all canned videos
    const matches: string[] = [];
    for (const [id, details] of this.cannedDetails) {
      if (
        norm.split(/\s+/).some((w) => details.title.toLowerCase().includes(w))
      ) {
        matches.push(id);
      }
    }

    if (matches.length > 0) {
      return matches.slice(0, opts?.maxResults ?? 10);
    }

    return Array.from(this.cannedDetails.keys()).slice(
      0,
      opts?.maxResults ?? 10,
    );
  }

  async getDetails(ids: string[]): Promise<YouTubeVideoDetails[]> {
    const out: YouTubeVideoDetails[] = [];
    for (const id of ids) {
      const found = this.cannedDetails.get(id);
      if (found) {
        out.push(found);
      } else {
        out.push({
          videoId: id,
          title: `YouTube video ${id}`,
          channel: 'Healthy Channel',
          durationSec: 600,
          privacyStatus: 'public',
          embeddable: true,
        });
      }
    }
    return out;
  }
}

